function GardenSoilAeratorSpikeMaker.completeMaking(m) local q=1.0+(GardenSoilAeratorSpikeMaker.getQualityBonus()/100); if GardenSoilAeratorSpikeMaker.maker then q=q+(GardenSoilAeratorSpikeMaker.maker.skill/140) end; q=math.min(2.5,q); GardenSoilAeratorSpikeMaker.productStock[m.productType]=(GardenSoilAeratorSpikeMaker.productStock[m.productType] or 0)+m.quantity; GardenSoilAeratorSpikeMaker.totalProducts=GardenSoilAeratorSpikeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenSoilAeratorSpikeMaker.maker then GardenSoilAeratorSpikeMaker.maker.itemsMade=GardenSoilAeratorSpikeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenSoilAeratorSpikeMaker.maker.skill=math.min(100,GardenSoilAeratorSpikeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bodalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardensoilaeratorspike.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
